package ru.devimind.chitalka.checks;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.*;
import android.graphics.pdf.PdfDocument;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.view.accessibility.*;
import android.webkit.WebView;
import org.json.*;
import ru.devimind.chitalka.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

/** Real input on generated books; existing library data is left untouched. */
public final class FullscreenChecks extends Instrumentation {
    private Activity activity;private Library library;private File folder;private SharedPreferences prefs;
    private final List<String> own=new ArrayList<>();private final JSONArray checks=new JSONArray();
    private String oldMode,oldAnimation;private boolean hadMode,hadAnimation;
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    private void expect(boolean value,String message){if(!value)throw new AssertionError(message);}
    private void pass(String message){checks.put(message);Bundle b=new Bundle();b.putString("check",message);sendStatus(0,b);}
    private View view(int id){AtomicReference<View> result=new AtomicReference<>();runOnMainSync(()->result.set(activity.findViewById(id)));return result.get();}
    private boolean shown(){View v=view(R.id.reader_controls);return v!=null&&v.isShown();}
    private AccessibilityNodeInfo find(AccessibilityNodeInfo node,String value){if(node==null)return null;if(value.equalsIgnoreCase(String.valueOf(node.getText()))||value.equals(String.valueOf(node.getContentDescription())))return node;if("android.webkit.WebView".contentEquals(node.getClassName()))return null;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo result=find(node.getChild(i),value);if(result!=null)return result;}return null;}
    private void tap(String value){for(int i=0;i<50;i++){AccessibilityNodeInfo node=find(getUiAutomation().getRootInActiveWindow(),value);while(node!=null&&!node.isClickable())node=node.getParent();if(node!=null&&node.performAction(AccessibilityNodeInfo.ACTION_CLICK)){SystemClock.sleep(250);return;}SystemClock.sleep(100);}throw new AssertionError("Missing "+value);}
    private void point(long down,long time,int action,float x,float y){MotionEvent event=MotionEvent.obtain(down,time,action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);sendPointerSync(event);event.recycle();}
    private void press(View v,float x,float y,long hold){int[] at=new int[2];runOnMainSync(()->v.getLocationOnScreen(at));long down=SystemClock.uptimeMillis();point(down,down,MotionEvent.ACTION_DOWN,at[0]+v.getWidth()*x,at[1]+v.getHeight()*y);if(hold>0)SystemClock.sleep(hold);point(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,at[0]+v.getWidth()*x,at[1]+v.getHeight()*y);SystemClock.sleep(450);}
    private void centre(int id){press(view(id),.5f,.5f,40);}
    private void dismissSystemHint(){for(int i=0;i<30;i++){AccessibilityNodeInfo node=find(getUiAutomation().getRootInActiveWindow(),"Got it");if(node!=null){node.performAction(AccessibilityNodeInfo.ACTION_CLICK);SystemClock.sleep(400);return;}SystemClock.sleep(100);}}
    private void swipe(int id,boolean vertical){View v=view(id);int[] at=new int[2];runOnMainSync(()->v.getLocationOnScreen(at));long down=SystemClock.uptimeMillis();for(int i=0;i<=12;i++){float f=i/12f,x=at[0]+v.getWidth()*(vertical?.5f:.85f-.65f*f),y=at[1]+v.getHeight()*(vertical?.8f-.6f*f:.5f);point(down,SystemClock.uptimeMillis(),i==0?MotionEvent.ACTION_DOWN:MotionEvent.ACTION_MOVE,x,y);SystemClock.sleep(18);}point(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,at[0]+v.getWidth()*(vertical?.5f:.2f),at[1]+v.getHeight()*(vertical?.2f:.5f));SystemClock.sleep(600);}
    private String js(String expression)throws Exception{CountDownLatch done=new CountDownLatch(1);AtomicReference<String> result=new AtomicReference<>();runOnMainSync(()->((WebView)activity.findViewById(R.id.book_body)).evaluateJavascript(expression,value->{result.set(value);done.countDown();}));expect(done.await(8,TimeUnit.SECONDS),"JS callback");return result.get();}
    private JSONObject ready()throws Exception{for(int i=0;i<100;i++){if(view(R.id.book_body)!=null){String s=js("window.Reader?Reader.snapshot():null");if(!"null".equals(s)){JSONObject value=new JSONObject(s);if(!value.getBoolean("busy")){SystemClock.sleep(200);return value;}}}SystemClock.sleep(100);}throw new AssertionError("Reader ready");}
    private void open(String id)throws Exception{Method method=MainActivity.class.getDeclaredMethod("showBookDetails",String.class);method.setAccessible(true);runOnMainSync(()->{try{method.invoke(activity,id);}catch(Exception e){throw new RuntimeException(e);}});tap("Читать");}
    private void bars(boolean visible){AtomicReference<WindowInsets> insets=new AtomicReference<>();runOnMainSync(()->insets.set(activity.getWindow().getDecorView().getRootWindowInsets()));expect(insets.get()!=null&&insets.get().isVisible(WindowInsets.Type.statusBars())==visible&&insets.get().isVisible(WindowInsets.Type.navigationBars())==visible,"System bars visible="+visible);}
    private void full(int id){View page=view(id);int[] size=new int[6];runOnMainSync(()->{size[0]=page.getWidth();size[1]=page.getHeight();size[2]=activity.getWindow().getDecorView().getWidth();size[3]=activity.getWindow().getDecorView().getHeight();android.graphics.Insets cutout=activity.getWindow().getDecorView().getRootWindowInsets().getInsets(WindowInsets.Type.displayCutout());size[4]=cutout.left+cutout.right;size[5]=cutout.top+cutout.bottom;});expect(size[0]==size[2]-size[4]&&size[1]==size[3]-size[5],"Reading occupies available display: "+Arrays.toString(size));expect(!shown(),"Reader controls hidden");bars(false);}
    private void shot(String name)throws Exception{SystemClock.sleep(500);Bitmap bitmap=getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(folder,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    private void pdfReady(String id,int page){for(int i=0;i<100;i++){Library.BookRow row=library.book(id);if(view(R.id.pdf_page)!=null&&row.page==page&&!row.started.isEmpty()){SystemClock.sleep(350);return;}SystemClock.sleep(100);}throw new AssertionError("PDF page ready");}
    private Object field(Object owner,String name)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
    private void pinch(View view){runOnMainSync(()->{long down=SystemClock.uptimeMillis()-500;MotionEvent.PointerProperties[] properties=new MotionEvent.PointerProperties[2];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[2];for(int i=0;i<2;i++){properties[i]=new MotionEvent.PointerProperties();properties[i].id=i;properties[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].y=view.getHeight()/2f;coords[i].pressure=1;coords[i].size=1;}for(int step=0;step<10;step++){float span=60+Math.max(0,Math.min(step-1,6))*60;coords[0].x=view.getWidth()/2f-span;coords[1].x=view.getWidth()/2f+span;int count=step==0||step==9?1:2;int action=step==0?MotionEvent.ACTION_DOWN:step==1?MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT):step==8?MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT):step==9?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;MotionEvent event=MotionEvent.obtain(down,down+step*40,action,count,properties,coords,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);view.dispatchTouchEvent(event);event.recycle();}});}
    private void runChecks()throws Exception{
        File fb2=new File(folder,"fullscreen.fb2");StringBuilder source=new StringBuilder("<FictionBook xmlns='http://www.gribuser.ru/xml/fictionbook/2.0'><description><title-info><book-title>Полноэкранное чтение "+UUID.randomUUID()+"</book-title></title-info></description><body><section><title><p>Глава для чтения</p></title>");for(int i=0;i<80;i++)source.append("<p>Книжная страница без лишних панелей. Читаем, замечаем и сохраняем мысли. Это абзац "+i+".</p>");source.append("</section></body><body name='notes'><section id='n1'><p>Проверочное примечание</p></section></body></FictionBook>");try(Writer out=new OutputStreamWriter(new FileOutputStream(fb2),"UTF-8")){out.write(source.toString());}String bid=library.importBook(Uri.fromFile(fb2));own.add(bid);
        File pdf=new File(folder,"fullscreen.pdf");PdfDocument document=new PdfDocument();for(int i=1;i<=2;i++){PdfDocument.Page page=document.startPage(new PdfDocument.PageInfo.Builder(600,800,i).create());Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setTextSize(24);page.getCanvas().drawText("Fullscreen PDF "+i+" / "+UUID.randomUUID(),35,65,paint);for(int n=0;n<16;n++)page.getCanvas().drawText("Read on the entire display. Line "+n,35,130+n*32,paint);document.finishPage(page);}try(OutputStream out=new FileOutputStream(pdf)){document.writeTo(out);}finally{document.close();}String pid=library.importBook(Uri.fromFile(pdf));own.add(pid);
        prefs.edit().putString("reader_mode","pages").putString("page_animation","none").commit();activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));runOnMainSync(()->activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON));
        open(bid);JSONObject before=ready();dismissSystemHint();full(R.id.book_body);shot("fb2-fullscreen");pass("FB2 открывается на весь доступный экран без панелей и системных полос");
        int height=view(R.id.book_body).getHeight();centre(R.id.book_body);expect(shown(),"Centre reveals FB2 controls");JSONObject after=ready();expect(height==view(R.id.book_body).getHeight()&&before.toString().equals(after.toString()),"Overlay leaves page and anchor unchanged");shot("fb2-controls");centre(R.id.book_body);expect(!shown(),"Second centre tap hides controls");press(view(R.id.book_body),.1f,.5f,40);expect(!shown(),"Edge tap ignored");pass("Центр показывает и скрывает управление поверх текста без изменения страницы; край не открывает меню");
        swipe(R.id.book_body,false);expect(ready().getInt("page")>before.getInt("page")&&!shown(),"Swipe turns without menu");pass("Свайп FB2 перелистывает страницу, не открывая управление");
        js("(function(){var a=document.createElement('a');a.id='central-note';a.href='https://chitalka.invalid/note/n1';a.textContent='Примечание';a.style='position:fixed;left:35%;top:45%;width:30%;height:10%;z-index:99;background:#888';document.body.appendChild(a);})()");SystemClock.sleep(400);shot("link-target");expect("true".equals(js("!!document.elementFromPoint(innerWidth/2,innerHeight/2).closest(\'a\')")),"Central link target: "+js("document.elementFromPoint(innerWidth/2,innerHeight/2).outerHTML"));centre(R.id.book_body);tap("К чтению");expect(!shown(),"Central footnote opens note, not controls");js("document.getElementById('central-note').remove()");pass("Ссылка на примечание в центральной зоне сохраняет своё действие");
        js("(function(){var p=document.querySelector('p'),r=document.createRange();r.selectNodeContents(p);var s=window.getSelection();s.removeAllRanges();s.addRange(r);})()");centre(R.id.book_body);expect(!shown(),"Existing selection does not trigger controls");js("window.getSelection().removeAllRanges()");press(view(R.id.book_body),.5f,.5f,650);expect(!shown(),"Long press does not trigger controls");js("window.getSelection().removeAllRanges()");pass("Выделение текста и долгое нажатие не вызывают панель чтения");
        centre(R.id.book_body);tap("Конспект");tap("Мои мысли");tap("+  Моя мысль");runOnMainSync(()->((android.widget.EditText)activity.findViewById(R.id.note_body)).setText("Мысль в полноэкранном чтении"));tap("Готово");tap("Закрыть конспект");expect(!shown()&&library.notes(bid).size()==1,"Notebook returns to reading");pass("Конспект доступен после центрального нажатия; запись сохраняется, закрытие возвращает к чтению");
        centre(R.id.book_body);runOnMainSync(activity::onBackPressed);expect(!shown(),"Back hides controls first");runOnMainSync(activity::onBackPressed);SystemClock.sleep(450);expect(view(R.id.book_details)!=null,"Back exits to card");bars(true);pass("Назад скрывает управление, затем открывает карточку и возвращает системные полосы");
        prefs.edit().putString("reader_mode","scroll").commit();tap("Читать");ready();full(R.id.book_body);swipe(R.id.book_body,true);expect(Double.parseDouble(js("window.scrollY"))>0&&!shown(),"Continuous scroll works without controls");SystemClock.sleep(650);centre(R.id.book_body);expect(shown(),"Centre works after scroll settles");centre(R.id.book_body);pass("Непрерывная прокрутка работает на весь экран; после остановки центр показывает управление");
        open(pid);pdfReady(pid,1);full(R.id.pdf_page);expect(!view(R.id.pdf_controls).isShown()&&!view(R.id.pdf_zoom_controls).isShown(),"PDF chrome hidden");shot("pdf-fullscreen");View image=view(R.id.pdf_page);int h=image.getHeight();centre(R.id.pdf_page);expect(shown()&&view(R.id.pdf_controls).isShown()&&view(R.id.pdf_zoom_controls).isShown()&&h==image.getHeight(),"All PDF controls overlay page");shot("pdf-controls");centre(R.id.pdf_page);expect(!shown(),"PDF centre hides all");pass("PDF занимает экран; центр показывает и скрывает навигацию и масштаб без изменения размеров страницы");
        pinch(image);expect((Float)field(image,"scale")>1&&!shown()&&library.book(pid).page==1,"Pinch zoom without menu or page turn");press(image,.5f,.5f,650);expect(!shown(),"PDF long press ignored");centre(R.id.pdf_page);tap("Страница");centre(R.id.pdf_page);swipe(R.id.pdf_page,false);pdfReady(pid,2);expect(!shown(),"PDF swipe without menu");pass("Масштаб двумя пальцами, долгое нажатие и перелистывание PDF не открывают меню");
        runOnMainSync(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));SystemClock.sleep(700);full(R.id.pdf_page);expect(library.book(pid).page==2,"PDF rotation retains page");centre(R.id.pdf_page);expect(shown(),"Landscape centre works");runOnMainSync(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));SystemClock.sleep(700);centre(R.id.pdf_page);expect(!shown(),"Portrait centre works");runOnMainSync(activity::onBackPressed);SystemClock.sleep(450);bars(true);tap("Читать");pdfReady(pid,2);full(R.id.pdf_page);pass("Поворот и повторное открытие PDF сохраняют страницу и полноэкранный режим");
    }
    @Override public void onStart(){Bundle result=new Bundle();JSONObject report=new JSONObject();try{library=new Library(getTargetContext());folder=new File(getTargetContext().getFilesDir(),"fullscreen-checks-0.1.9");folder.mkdirs();prefs=getTargetContext().getSharedPreferences("settings",0);hadMode=prefs.contains("reader_mode");hadAnimation=prefs.contains("page_animation");oldMode=prefs.getString("reader_mode","scroll");oldAnimation=prefs.getString("page_animation","none");runChecks();report.put("result","PASS");result.putString("result","PASS: "+checks.length()+" groups");}catch(Throwable error){try{report.put("result","FAIL").put("error",error.toString());}catch(Exception ignored){}result.putString("result","FAIL: "+error);}
        finally{if(activity!=null)runOnMainSync(activity::finish);for(String id:own)try{library.deleteBook(id,true);prefs.edit().remove("anchor_"+id).commit();}catch(Exception ignored){}if(prefs!=null){SharedPreferences.Editor e=prefs.edit();if(hadMode)e.putString("reader_mode",oldMode);else e.remove("reader_mode");if(hadAnimation)e.putString("page_animation",oldAnimation);else e.remove("page_animation");e.commit();}}
        try{report.put("checks",checks);try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(folder,"checks.json")),"UTF-8")){out.write(report.toString(2));}}catch(Exception ignored){}
        finish("PASS".equals(report.optString("result"))?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
